from manual_content import PAGES as CORE, text,table,eq,note,diagram,picture


def p(part,title,lead,blocks):return dict(part=part,title=title,lead=lead,blocks=blocks)


def technical(summary,root):
    s=summary;wide=s['wide'];narrow=s['narrow'];external=s['external'];motion=s['motion']
    updates=[
      p('最终版 · 阅读与证据','A1  最终交付范围','先读本篇掌握当前实测事实，再读后面的系统原理、源码路线和教学模块。',[
        text('做成的产品','TileLab 是针对已标定纹理瓷砖的 FPGA 裂纹候选检测与人工复核竞赛原型。电脑 HDMI 输入连续运动画面，PYNQ-Z2 在可编程逻辑中检测并画框；板端网络传回同帧证据；电脑按产品编号存图并供人工审核。'),
        diagram('architecture'),
        table('三个交付层',['部分','最终职责'],[['FPGA / PL','HDMI、灰度、双尺度暗谷、有限邻域补全、局部框、产品跟踪、最佳帧及校验。'],['Vitis / ARM','DMA 和 DDR 帧槽、事件引用与确认、无损编码、TCP 发送、健康与恢复。'],['电脑 / PC','预览与事件调度、图片校验、容量限制、SQLite 存档、人工复核、测试输入。']]),
        note('范围必须讲清','目前没有真实摄像头或工厂流水线。真实照片加人工生成的运动用于测试；可运行的检测闭环不等于工业识别精度认证。最新外部大理石测试暴露了明显漏检，不能把本作品介绍为通用材质检测器。')]),
      p('最终版 · 验收结果','A2  当前结果与适用边界','下面区分“算对了”和“识别好了”：两者需要不同的测试。',[
        table('最终实板证据',['检查','实测结果'],[
          ['身份和构建','PL 图像来自 V1.52 的已布线产物；电脑工程 V1.53；固件 0x12b00。下载后核对 BIT、XSA、ELF 内容哈希和启动号。'],
          ['历史同图对照',f"窄尺度、双尺度各 {wide['samples']} 张；原图、掩码与区域计算一致。两配方均为 17 张裂纹报警、33 张正常零报警。"],
          ['弱裂纹改进',f"像素召回 {100*narrow['pixel_recall']:.2f}% → {100*wide['pixel_recall']:.2f}%；双尺度像素精确率 {100*wide['pixel_precision']:.2f}%。这是重复使用的开发数据。"],
          ['连续移动留证',f"120 秒，自动留存 {motion['automatic_archives']} 条不同产品证据；输入实测约 {motion['measured_input_fps']:.2f} fps；测试窗口内无新增五类错误计数。"],
          ['电脑软件',f"{s['host_tests']} 项单元回归通过；另有共享命令解析、界面与实际运动/存档检查。"],
          ['外部材料',f"新增 MCS2 RGB 的 24 张裂纹图，仅 {external['crack_alarms']} 张报警，像素召回 {100*external['pixel_recall']:.2f}%。没有正常整砖，不能算图像级误报率。"]]),
        note('为什么不能写“准确率 98%”','像素精确率描述被标记的像素有多少落在裂纹标签中；它不包含大量漏掉的裂纹。图像报警率、像素召回、定位误差应分别报告。历史 17/17 的报警也不是独立工厂检出率。')]),
      p('最终版 · 新算法','A3  双尺度弱裂纹如何计算','扩大弱点支持窗口，同时保留原来的强种子，避免大窗口直接把背景纹理变成新裂纹。',[
        eq('Y = (77R + 150G + 29B) >> 8','R、G、B 是 0~255 的颜色值；右移 8 位等价于整数除以 256。系数和为 256，输出仍为 8 位亮度。'),
        eq('S_r(x,y) = max(0, max_d[min(Y(x+r dx,y+r dy), Y(x-r dx,y-r dy)) - Y(x,y)])','d 取水平、垂直和两条对角线。裂纹中心比两边都暗才得到正分数，单侧台阶边缘被 min 抑制。r 分别为 8 与 16。'),
        eq('M_0 = ROI AND (S_8 > 90)；W = ROI AND [(S_8 > 45) OR (S_16 > 45)]'),
        eq('M_(k+1) = M_k OR [W AND (3×3 邻域内 M_k 的点数 >= 3)]；k = 0,1,2,3','只有四轮有限传播，不等同于软件中遍历整幅图的无界连通搜索；不会自动补完整条很弱且没有种子的裂纹。'),
        text('对应的电路','dual_scale_valley.v 并行计算两个窗口，补齐延迟后合并弱支持；video_bypass.v 按配置 bit27 选择。灰度、种子、邻域和框均在 FPGA 内计算。ARM 只写参数。'),
        note('一次手算','中心亮度为 80，某方向两侧为 160、170，暗谷分数为 80，尚未达到高阈值 90，但超过低阈值 45。若它的 3×3 邻域已有至少 3 个强点/上一轮支持点，就能在下一轮加入。没有邻域支持则保持未检出。')]),
      p('最终版 · 实验取舍','A4  为什么拒绝盲目降阈值','降低阈值能让更多地方变红，但这不一定提高产品质量判断能力。',[
        text('外部初测','24 张新的大理石照片在固定参数下进行实板测试；实际输出与参考公式一致，裂纹报警却只有 1/24。这说明材质、对比度和采集尺度超出了原配方适用范围。'),
        text('随后做的开发实验','从已检查过的外部数据中取 4 张实采图，比较不同高阈值。高阈值 16 能让 4 张都报警，但像素精确率仅约 9.13%；阈值 8 时精确率约 1.77%。这些样本此后属于开发数据，不能再次称为盲测。'),
        table('问题归因与后续动作',['现象','需要的改进'],[['没有高分种子','改进对弱暗线的特征和方向一致性，不能只增加生长轮数。'],['低阈值大量纹理候选','先验证去噪、背景归一化或方向线支持，再用正常材料标定误报。'],['不同颜色/尺度表现变化','控制照明和曝光，按实际材料建立配方，保持物理裂纹宽度与像素尺度一致。'],['缺少正常整砖对照','采集不同批次的正常/缺陷产品，按物理产品划分开发集与独立测试集。']]),
        note('本版发布取舍','保留已验证的纹理瓷砖配方及人工审核；没有将低阈值实验设成默认，也没有宣称改善了跨材质识别。新增材料能力应作为下一阶段，有新的独立数据才重新给出结论。')]),
      p('最终版 · 同步与网络','A5  输入状态不会拖住采集','播放器状态只是本机软件的采用证明，板端健康与帧码才补充说明真实采集。',[
        text('新的状态读取方式','后台线程每约 0.25 秒读取播放器状态；HTTP 状态接口只读取内存快照，不等待文件 I/O。缓存使用单调时钟计算年龄；读取出错或超过 1.5 秒的新鲜度时，撤销 READY 和身份确认。暂停/继续意图由独立控制锁保护。'),
        eq('有效确认 = 请求编号一致 AND 播放器启动身份一致 AND 状态未过期','播放器已经采用输入，不等于 HDMI 电气链路已经锁定。板端必须另外报告完整帧、正确分辨率、启动号和 CRC。'),
        text('本次网络适配','电脑网口当前为 192.168.33.30/24；开发板通过 JTAG 配置为 192.168.33.10。旧版固定 169.254 地址导致连接失败，本版允许 RFC1918 私网或链路本地地址，启动时读取下载记录中的实际地址。电脑原网口设置没有更改。'),
        note('颜色保真边界','本次实采与源 PNG 存在颜色变换；逐通道图案相关性约 0.999，但 RGB 字节并不完全相等。尚未隔离 Windows/GPU 色彩设置的具体原因。检测参考模型使用实际采集 RGB；PL 到电脑的无损传输验证不代表源 PNG 到 HDMI 完全无损。'),
        text('代码入口','host/live_status_cache.py、host/stimulus_status.py、host/workstation.py、.sdk/program_ethernet.tcl 与 reports/programmed_v153.json。具体私网地址要按现场网段设置，不能直接照抄到不同网络。')]),
      p('最终版 · 复现与接手','A6  从交付包开始操作','按这个顺序启动；读完后面的原理篇，再回来复现实验。',[
        table('操作顺序',['步骤','动作'],[['1 · 连接','电脑 HDMI → HDMI IN；HDMI OUT → 显示器；PROG UART USB → 电脑；以太网 → 电脑网口；使用正确电源。'],['2 · 显示','Windows 扩展显示器中，提供给板卡的输入设置为 1280×720、60 Hz；测试窗口占满这一屏。'],['3 · 下载','运行 .sdk/program_checked.tcl，传入同网段、未占用的板端私网地址；这是掉电即失的 JTAG 配置。'],['4 · 启动','运行“启动以太网工作站.bat”；打开 http://127.0.0.1:8770/，先看连接/完整帧健康。'],['5 · 配方','先空传送带，选择“本机 HDMI 瓷砖 · 双尺度弱裂纹增强”，再选择“真实瓷砖照片连续移动”。'],['6 · 留证','先预览确认稳定，再启用有容量上限的自动留图；打开一条产品证据核对原图、掩码与参数，填写人工结论。'],['7 · 验收','运行 scripts/board_submission_acceptance.py；旧 reports 不覆盖，重复测试应使用新证据目录。']]),
        text('工程形态','本版 XPR、Block Design 和生成目录由 Vivado 实际生成；硬件下载文件复用已布线且经本次实板验证的相同 RTL 产物。.sdk 包含真实 Vitis 平台、应用与构建脚本；它本身就是工作区。'),
        note('后文阅读边界','后面的基础教学沿用已验证的系统原理。V1.32 命名的时序审查、历史示例和审计脚本明确属于历史证据；当前双尺度、实板结果和新状态缓存以 A1~A6 为准。')])]
    core=copy.deepcopy(CORE)
    core[0]['blocks']=[text('读者目标','先理解产品与证据，再学习像素算法、时钟、DMA、事务，最后完成术语和手算练习。当前结果以更新篇 A1~A6 为准；历史测试不能替代本版验收。'),table('阅读路线',['目标','顺序'],[['答辩产品','A1~A2 → 产品篇 → 优势与限制 → 答辩问答。'],['掌握原理','A3 → 算法篇 → 硬件篇 → 板端与电脑篇 → 教学模板。'],['独立复现','A5~A6 → 接线/构建 → 源码路线 → 测试入口。']]),note('证据分级','实板：真正经过 HDMI、PL、DMA、TCP；离线/仿真：证明公式或电路关系；推导：由时钟和字节数计算；计划：尚未实现。请始终区分这四种证据。')]
    core[24]['blocks'][-1]=note('当前接线配置','板卡 RJ45 直连电脑。当前电脑网口 192.168.33.30/24，板端 192.168.33.10，TCP 9133；其他电脑应选择同网段未占用的私网地址。169.254.200.10 属于历史自动私有地址示例。网页运行在本机 127.0.0.1:8770，与板卡 IP 不同。')
    core[36]['blocks'][-1]=note('提交范围冻结','V1.53 冻结为标定材料的竞赛提交候选；未完成的跨材质识别、实际相机与工厂验收保留为后续路线。不要在拍摄前随意更改参数、代码或输入缩放。')
    core[53]['blocks'].append(text('本次新增外部数据','MCS2 RGB：24 张大理石裂纹照片和标签，作者 Vrochidou 等，2023，CC BY 4.0。来源 https://github.com/MachineLearningVisionRG/mcs2-dataset 。本版初测 1/24 报警；之后检查过的样本转为开发数据。MVTec 回放缩放、背景合成和实采 RGB 均是衍生测试素材，继承其 CC BY-NC-SA 4.0 许可。'))
    core[34]=p('当前结果导航','34  本版实现与验收入口','详细当前结果已在更新篇列出；本页把证据与结论连接起来。',[
        table('可以核对的文件',['文件','验证什么'],[['reports/v153/real_board/summary.json','旧配方 50 张真实 HDMI 回归。'],['reports/v153/real_board_wide/summary.json','双尺度 50 张同图计算与效果。'],['reports/v153/external_mcs2/summary.json','外部材质 24 张初测及颜色变换记录。'],['reports/v153/submission_motion/summary.json','连续运动、产品唯一编号、最佳帧和实际存档。'],['reports/v153/host_tests_final.log','最终主机单元测试结果。'],['reports/timing_summary.rpt','沿用硬件的建立/保持时序报告。']]),
        note('时序余量',f"已布线图像 WNS +0.030 ns、WHS +0.050 ns，BRAM 74.64%。余量较小，不建议直接提高时钟；任何 RTL/约束修改都要重新实现、检查和上板。"),
        text('复现要求','记录输入、配方、固件/启动号、恢复代次和测试脚本哈希；错误计数比较的是测试窗口内增量，不能把旧累计值清零后描述为从未发生过问题。')])
    core[35]=p('当前结果导航','35  实际证据与截图质量','图片留存是系统行为的一部分，不能只靠挑一张好看的效果图。',[
        table('本次自动留图',['指标','结果'],[['产品证据数量',str(motion['automatic_archives'])],['唯一编号数量',str(motion['unique_product_ids'])],['完整瓷砖标记','逐条检查 selection_full_tile 为真'],['源码帧码测得最大居中误差',f"{motion['source_center_error_max_px']} px；这是回放图的几何误差，不是实际毫米定位精度。"],['完整性','逐条重建 BGR+掩码，核对 PL 像素 CRC，存档读取核对 SHA256。']]),
        text('网络指标怎样报告','网口协商 1 Gbps 是链路速率；有效负载吞吐、请求时间、解码时间必须从同事件传输比较中读取。720p60 表示 FPGA 输入处理，不表示电脑保存 60 张完整截图每秒。'),
        note('历史网络实验','旧版本三种编码对照保留在历史证据中；本版重新核对传输和事件完整性。不要将旧测量直接写成本次新测速。')])
    # Keep historical release labels where they describe historical experiments.
    # Local execution paths point to the current project; public source uses this
    # preserved directory name under project/ in the submission repository.
    def replace(v):
        if isinstance(v,str):return v.replace('D:/Vivado/pynq_z2_tile_v1_32',str(root).replace('\\','/')).replace('pynq_z2_tile_v1_32.sdk','pynq_z2_tile_v1_53.sdk')
        if isinstance(v,list):return [replace(x) for x in v]
        if isinstance(v,tuple):return tuple(replace(x) for x in v)
        if isinstance(v,dict):return {k:replace(x) for k,x in v.items()}
        return v
    return [core[0],*updates,*replace(core[1:])]


def filming(summary):
    scenes=[
      ['00:00-00:15','问题与目标','本人出镜或产品标题；展示瓷砖裂纹近景。','人工巡检连续画面容易漏看细裂纹，我们用 FPGA 给出裂纹候选并保留证据。'],
      ['00:15-00:45','真实硬件连接','手机一镜拍电脑 HDMI、板卡 IN/OUT、USB、网线及输出显示器。','目前用真实照片回放替代摄像头，视频实际经过 PYNQ-Z2；检测在 FPGA 内完成。'],
      ['00:45-01:20','持续运动检测','外接显示器持续拍 3~4 块瓷砖，不切镜隐藏移动过程。','产品没有在中央停留；红框由板上电路生成，视频输入不含预画的检测框。'],
      ['01:20-02:10','自动留证与人工复核','电脑录屏：事件列表 → 某产品 → 原图/掩码 → 放大 → 人工结论 → 保存。','一块产品保留一张较好的缺陷证据；原图、掩码、参数和身份一起记录，便于复核误报。'],
      ['02:10-02:45','FPGA 与 ARM 分工','架构图配合 RTL/Block Design 与一条实际证据。','PL 做像素特征、补全、局部框和产品跟踪；ARM 做 DMA、缓存和网络；电脑做存档与审核。'],
      ['02:45-03:20','可核对的测量','当前 summary、时序报告和同图对照；圈出单位与样本数。','历史样本召回 26.37% 到 28.20%，不是普适准确率；实际视频输入约 60 帧每秒。'],
      ['03:20-03:55','可靠性与资源取舍','演示暂停预览/继续，查看事件和状态；说明有界缓存。','预览可降速，缺陷事件优先；容量受控；帧身份与校验避免图、框、参数对错帧。'],
      ['03:55-04:20','诚实展示边界','外部材料测试表与一张漏检图；展示后续路线。','固定配方不适用于所有材料，新的大理石测试漏检明显。后续需要照明、特征和独立产品数据改进。'],
      ['04:20-04:30','交付与结束','GitHub 页面、工程目录、PDF 封面；本人结语。','作品交付完整源码、构建与测试脚本、技术手册，后续可接入兼容视频采集设备。']]
    return [
      p('拍摄方案 · 总目标','01  拍一条可相信的演示','建议成片 4 分 30 秒，另保存 8~10 分钟完整操作母片。实际平台时长、格式和大小限制必须以提交页面为准。',[
        text('必须证明的五件事','真实板卡参与；瓷砖不停带；红框来自 FPGA；同一块产品留存最佳证据；人工能够复核并追溯参数。优先让观众看懂这五点，再讲性能。'),
        text('三种素材分开标注','手机实拍用于证明接线和外接显示器输出；电脑录屏用于展示复核操作；架构图/动画用于解释原理。真实照片回放必须标注“真实照片 / 合成运动 / HDMI 实板测试”。'),
        note('禁止用作替代证明','不能把预先画好红框的视频送入 HDMI，再当成 FPGA 检测；不能把离线算法截图冒充实板结果；不能剪掉输入停顿后声称连续运动。图像是模拟输入，但检测与传输必须是真实运行。'),
        text('文件组织','建立 filming/raw_camera、raw_screen、audio、figures、edit、final 五类目录；原始镜头只读保留，成片另存，不覆盖原始证据。文件名使用日期_镜头号_第几次拍摄。')]),
      p('拍摄方案 · 设备','02  器材和线材清单','先把硬件稳定摆好，再开始录制，避免反复插拔。',[
        table('需要的物品',['物品','用途与检查'],[['PYNQ-Z2 与正确电源','稳定供电；不要仅凭 USB 插上就认为板卡已充分供电。电源规格按板卡标识和官方手册。'],['USB 数据线','Micro-B 接板上 PROG UART，另一端接电脑；必须支持数据，设备管理器应出现 FTDI / COM 口。'],['两根 HDMI 线','电脑 → HDMI IN；HDMI OUT → 显示器。普通合格 HDMI 线即可满足 720p60，无需先买昂贵线。'],['网线','板卡 RJ45 → 电脑网口；推荐常见 Cat5e/Cat6，协商状态检查 1 Gbps。'],['手机、支架、耳机麦克风','手机固定拍硬件与显示器；优先单独录清楚讲解音频。'],['桌面标签','给 HDMI IN、HDMI OUT、USB/JTAG、Ethernet 贴箭头，镜头中能看清流向。']]),
        note('摄像头说明','摄像头不一定原生提供 HDMI。USB、MIPI、GigE 工业相机常需要不同接口或桥接。本次不采购摄像头；演示不要说成已经接入工业相机。')]),
      p('拍摄方案 · 接线','03  接线与桌面摆放','电脑、板卡和外接显示器同时进入镜头，是最直接的真实性证明。',[
        diagram('wiring'),
        text('接线顺序','断电检查跳线与接头 → 接电脑 HDMI 到板卡 IN → 接板卡 OUT 到显示器 → 接网线 → 接 PROG UART USB 数据线 → 正确供电并开机。显示器菜单选择实际接线的 HDMI 入口。'),
        text('摆放建议','板卡放在电脑与显示器之间，避免线压住板卡；芯片和接口朝镜头。固定手机俯拍约 30~45 度，让接口标签与屏幕同时可辨。不要用手持续托住板卡。'),
        note('保留连续镜头','连接讲解结束后保持手机拍摄，转入真实移动画面；尽量用一个连续镜头同时拍到板卡和输出屏，不只录电脑里的播放器。')]),
      p('拍摄方案 · 启动','04  开拍前完整检查','每次掉电之后重新下载，先确认身份和完整帧健康，不能靠旧预览判断板卡在线。',[
        table('开拍检查',['项目','合格状态'],[['USB/JTAG','XSDB 能看到 Xilinx TUL、xc7z020 和 Cortex-A9；COM20 仅是本机历史编号。'],['输入显示','扩展显示中的板卡输入为 1280×720、60 Hz；测试窗口无边框占满这一屏。'],['网络','电脑与板卡处于同一私网；本机示例 192.168.33.30 与 192.168.33.10。不要将示例地址照抄到其他现场。'],['版本','下载哈希与交付清单一致，固件为 0x12b00，启动号与本次记录一致。'],['图像','完整帧采集正常，帧计数持续增加；播放器的 READY 与板端健康分别检查。'],['参数','空传送带时选择双尺度配方，高90、低45、四级支持；等实采参数生效。'],['存储','默认仅预览；准备正式自动留证时启用容量上限，剩余空间足够。']]),
        note('临场不要做的事','不要修改 RTL 或提高频率后直接录成片。当前时序余量很小；所有演示使用已通过实板测试的固定 BIT/ELF。不要同时启动两套工作站占用同一板卡。')]),
      p('拍摄方案 · 测试场景','05  拍哪些输入，按什么顺序','先拍已验证材料的正常/裂纹对照，再展示外部材料限制。',[
        table('场景目录',['输入','用途'],[['station_6','空传送带，用于排队清空、配方切换和演示无产品。'],['real_video','真实 MVTec 瓷砖照片连续移动；正式主镜头，名义速度 480 px/s。'],['real_000 / real_005','静态裂纹开发样本，便于讲解原图、掩码和局部框；不是独立测试。'],['holdout_video','新增大理石照片的连续运动；用于展示跨材质边界，不能隐藏漏检。'],['holdout_000','外部材料静态例子，记录当前配方能否报警及原因。'],['video / fast','合成测试来源；只有标注合成时才用来解释速度与布局。']]),
        text('具体操作','先选择空传送带 → 读取状态 → 选择双尺度配方 → 开始预览 → 选择真实照片连续移动。确认运动持续后启用自动留图，等待 3~4 个缺陷产品通过，再暂停接收并打开证据。'),
        note('算法对照不能破坏运动叙事','静态对照单独拍，明确叫“同图参数对照”；连续运动主镜头不要为截图在中央停住瓷砖。现场不自动识别材料类别，切换材料需要人工选择经过标定的配方。')]),
      p('拍摄方案 · 成片结构','06  4分30秒时间线（上）','先展示问题和真实闭环，再解释电路。',[
        table('镜头安排',['时间 / 主题','画面','讲解要点'],[[r[0]+'\n'+r[1],r[2],r[3]] for r in scenes[:4]])]),
      p('拍摄方案 · 成片结构','07  4分30秒时间线（下）','性能需要单位、样本数和测试范围；最后主动说明限制。',[
        table('镜头安排',['时间 / 主题','画面','讲解要点'],[[r[0]+'\n'+r[1],r[2],r[3]] for r in scenes[4:]])]),
      p('拍摄方案 · 实拍细节','08  硬件镜头逐步拍法','至少拍三类真实镜头，每类录两次，第二次作为备用。',[
        text('H01 · 全景，10~15秒','手机固定，电脑、板卡、显示器一起出现。手指指出三层职责，不遮挡屏幕。开头留 2 秒静止，结尾留 2 秒，便于剪辑。'),
        text('H02 · 接口近景，20~30秒','依次移动镜头看 HDMI IN、OUT、PROG UART 和网线，读出标签与方向。这里可以慢速拍摄，但随后主运行画面恢复正常速度。'),
        text('H03 · 连续运行，至少60秒','手机保持固定，连续拍 3~4 块瓷砖通过以及裂纹红框；包含正常材料和裂纹材料，不只拍一个成功瞬间。记录实际拍摄时间和使用配方。'),
        text('H04 · 原图与输出的对照，15~20秒','展示电脑输入画面没有检测框，外接输出屏具有 FPGA 红框；如无法同时容纳两屏，使用连续转动镜头，不用两个无时间关联的短片代替。'),
        note('条纹或闪烁','先试 1080p30、曝光/快门 1/60，再试 1/120；固定曝光与白平衡，关闭手机自动美化/HDR以减少颜色变化。先录10秒检查条纹，确认后拍正式镜头。拍摄条纹不等同电路闪烁，应与裸眼和实采帧检查区分。')]),
      p('拍摄方案 · 电脑录屏','09  复核操作逐步录法','录整个操作过程，再剪成重点。不要把错误提示裁掉。',[
        text('S01 · 工作站首页','显示版本、板端连接、实时帧计数、材料配方与存储模式。录屏窗口尺寸建议 1920×1080，浏览器缩放以文字清晰为准。'),
        text('S02 · 自动留图','开启有上限的自动留图，等待实际缺陷事件进入列表；展示产品编号、帧号、时间和局部框。说明预览降频不等于 FPGA 降为同样帧率。'),
        text('S03 · 打开证据','选一张完整、居中的产品图。放大裂纹区域，切换原图与掩码，显示捕获参数和校验状态；不要先在图片编辑器中加工“改善”证据。'),
        text('S04 · 人工结论','将真实疑似裂纹标为“确认缺陷”，写一条简短备注并保存；另一条可展示误报复核。重新打开，确认结论已持久化，再导出 CSV/JSON。'),
        text('S05 · 暂停与继续','点击暂停，解释已准入的一条证据可能仍完成保存和确认；等待接口显示空闲后再操作。重新开始时检查最新画面，避免把冻结预览当成实时视频。'),
        note('录屏边界','电脑截图不能单独证明外接 HDMI 显示器的实际输出。它用于证明复核界面和证据链；必须配合 H03 的真实硬件镜头。')]),
      p('拍摄方案 · 可追溯证据','10  每个成功镜头保留什么','拍摄的作用是展示，测试记录的作用是支持结论，两者一起交付。',[
        table('关联材料',['记录','原因'],[['日期、版本、BIT/ELF SHA256','确认拍的是哪个真实实现。'],['固件、启动号、恢复代次','区分重启前后的帧身份。'],['输入名、请求号、源帧码','确认测试来源和当前采用的输入。'],['产品编号、帧号、配置字','说明图、框和参数属于同一证据。'],['原图、掩码、校验状态','审核时可看原始数据，防止只剩标红图。'],['测试开始/结束计数','记录测试期间是否新增丢帧、无效帧、ACK/描述校验错误。'],['人工结论、备注、修订号','证明复核结果已保存，避免旧页面覆盖新结论。']]),
        note('拍摄日志模板','镜头号：____；日期：____；工程：____；输入：____；配方：____；启动号：____；产品/帧号：____；原图文件：____；屏幕稳定：____；补拍原因：____。')]),
      p('拍摄方案 · 讲解稿','11  可直接朗读的讲解稿（上）','正常语速分段录音，句子之间留停顿。不要一口气背完。',[
        text('产品开场','这是 TileLab，一套基于 PYNQ-Z2 的瓷砖裂纹候选检测与人工复核原型。我们关注连续移动产品的检查：发现疑似裂纹、画出位置、保存对应产品的较好画面，并让人能够回看审核。'),
        text('输入与硬件','目前没有购买工业相机，因此用真实瓷砖照片组成连续移动画面，经电脑 HDMI 输入板卡。另一根 HDMI 线把 FPGA 处理后的画面送到显示器。照片的运动是生成的，但检测、缓存和网络传输都在实际板卡上运行。'),
        text('算法原理','裂纹通常表现为比两侧更暗的细线。电路先把颜色变成灰度，再比较四个方向的两侧亮度。较强的暗线成为种子；较弱的点只有在附近已有足够支持时才加入。双尺度让弱支持同时参考较近和较远的背景，最后形成局部矩形框。'),
        text('系统分工','FPGA 持续处理像素，ARM 管理 DMA、DDR 和事件传输，电脑负责保存与人工审核。图像识别没有移到电脑上运行，电脑里的播放器也没有预先画检测框。')]),
      p('拍摄方案 · 讲解稿','12  可直接朗读的讲解稿（下）','讲清结果与局限，避免将竞赛原型夸成已投产设备。',[
        text('不停带留证','每块产品经过检查区域时，FPGA 跟踪其编号并挑选较完整、较居中的缺陷帧。产线画面持续运动，取图不要求它在中央停留。传回电脑的原图、掩码、框和参数属于同一条证据，可以人工标记确认缺陷或误报。'),
        text('测试结果',f"本次连续运动验收自动保留了 {summary['motion']['automatic_archives']} 条不同产品证据，实际输入帧率约为 {summary['motion']['measured_input_fps']:.2f} 帧每秒。历史同图开发集上，双尺度将裂纹像素召回从 26.37% 提升到 28.20%。我们同时验证了计算、帧身份、传输和存档一致性。"),
        text('限制说明','这些结果不代表所有瓷砖材质都达到相同精度。新增大理石测试中，当前配方漏检明显；直接降低阈值又产生大量背景候选。因此当前发布限定于已标定材料的候选检测与人工复核，后续重点是光学采集、弱裂纹特征和独立产品测试。'),
        text('交付结束','工程包含可复现的 Vivado 与 Vitis 构建、完整代码、测试记录和技术教学手册。我们可以在这个架构上接入兼容的视频采集设备，继续完善真实产线的精度和可靠性。')]),
      p('拍摄方案 · 数据与性能','13  性能画面怎么拍才准确','用当前记录支持当前结论，给每个数字写上单位和测试条件。',[
        table('可展示的数字',['数字','必须同时说明'],[['720p60 / 约60fps','这是 FPGA 输入处理；电脑预览/留图不是60张完整图片每秒。'],['WNS +0.030ns','已布线建立时序余量很小；不是延迟指标，也不是可随意超频的证明。'],['BRAM 74.64%','窗口、缓存和区域统计占用的片上存储比例。'],['26.37% → 28.20%','历史开发样本像素召回；注明50图、其中17裂纹和33正常。'],['24图，仅1图报警','外部新材料的固定参数初测；不能只展示像素精确率而隐藏漏检。'],['网口1Gbps','这是协商速率；有效吞吐与请求时间需要具体测速记录。']]),
        note('不应写的宣传语','“工业级全材质”“零漏检”“98%整体准确率”“YOLO识别”“永不丢数据”“全链路60fps截图”等都没有本工程证据支持。请使用“已标定材料”“裂纹候选”“有界队列”“实际实测范围”。')]),
      p('拍摄方案 · 剪辑','14  剪辑和字幕规范','剪辑帮助观众理解，不改变测试事实。',[
        text('画面布局','硬件运行镜头为主；电脑复核录屏可全屏展示；架构图用四个箭头说明数据流，不堆满专业缩写。中文字幕每行约15~22字，两行以内，字号足够阅读。'),
        text('转场原则','从硬件输出切到电脑证据时，用同一产品/帧号作连接。注明“录屏”和“实拍”。不要加快连续运动镜头后宣称实际线速，也不要将慢放当成检测吞吐下降。'),
        text('声音与隐私','麦克风靠近讲话者，保持一致音量；背景音乐低于讲解。关闭消息弹窗，检查是否露出私人聊天、账号令牌或无关文件。项目必要的版本和样本出处应保留。'),
        text('建议导出','MP4 / H.264 / 1080p / 30fps；比特率先试8~12Mbps。4.5分钟预计约270~405MB，这是编码预算推导，实际以导出文件为准；按比赛平台大小限制再调整。'),
        note('保留母片','保留无配乐、无遮挡原始镜头及完整录屏。成片压缩可能让细裂纹难看清，因此另外提供清晰原图/掩码和静态效果图。')]),
      p('拍摄方案 · 复核与交付','15  补拍标准与最终清单','成片前逐项检查；不合格的镜头重拍，测试失败的内容不能靠剪辑修好。',[
        table('检查项',['项目','合格标准','不合格时'],[['接口证明','板卡、IN/OUT方向和实际输出屏可辨','重新拍连续全景/近景。'],['运行状态','画面持续运动，无专门中心停顿','先修输入/采集，再重拍。'],['裂纹证据','原图、局部框、掩码和产品编号能对应','停止发布该镜头，排查身份与取图。'],['截图质量','完整产品且裂纹可见，文字能阅读','检查最佳帧选择与录屏缩放。'],['人工复核','结论保存后重开仍可读','先修数据库/并发问题。'],['数字与边界','所有数字注明范围，外部漏检不隐藏','修改字幕和讲解稿。'],['仓库链接','别人能够访问，源码与发布清单一致','完成上传与公开访问核对。']]),
        text('最终提供的文件','成片MP4；完整母片或备份；5~8张清晰效果图；技术PDF；本拍摄方案；完整代码仓库链接；精简工程ZIP；版本/哈希清单；数据来源与许可说明。'),
        note('当前分工','工程、测试和文档可自动整理；手机实拍、本人讲解与最终比赛表单需要你完成。本文件是一份可执行拍摄方案，不是已经拍摄好的实物演示视频。')])]
